    async def set_object_retention(
        self,
        request: SetObjectRetentionRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> ObjectLockState:
        """
        ─── Object Lock (ADR-0013) ──────────────────────────────────────────────

        Retention and legal hold are separate operations because their rules
        differ, which is also how S3 splits them. A legal hold can be lifted by
        anyone authorised to set it; a retention window can only ever be extended
        unless the mode is GOVERNANCE and the caller holds the bypass role.

        Locks attach to a VERSION, not to an object. On an unversioned bucket the
        object has exactly one version, so the distinction is invisible; on a
        versioned one it is the difference between protecting a document and
        protecting today's copy of it.
        SetObjectRetention applies or extends a retention window on an object's
        current version. Requires the parent bucket to have object lock enabled.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="SetObjectRetention",
                service_name="paladin.data.v1.ObjectService",
                input=SetObjectRetentionRequest,
                output=ObjectLockState,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

    async def set_object_legal_hold(
        self,
        request: SetObjectLegalHoldRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> ObjectLockState:
        """
        SetObjectLegalHold turns a legal hold on or off. A hold blocks deletion
        for as long as it is on, independently of any retention window, and is
        not subject to the GOVERNANCE bypass.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="SetObjectLegalHold",
                service_name="paladin.data.v1.ObjectService",
                input=SetObjectLegalHoldRequest,
                output=ObjectLockState,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

    async def get_object_lock(
        self,
        request: GetObjectLockRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
        use_get: bool = False,
    ) -> ObjectLockState:
        """
        GetObjectLock reads the current lock state. Returns an empty state — not
        NOT_FOUND — for an object with no lock, so callers can render "unlocked"
        without special-casing an error.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="GetObjectLock",
                service_name="paladin.data.v1.ObjectService",
                input=GetObjectLockRequest,
                output=ObjectLockState,
                idempotency_level=IdempotencyLevel.NO_SIDE_EFFECTS,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
            use_get=use_get,
        )

    async def set_object_taint(
        self,
        request: SetObjectTaintRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> Object:
        """
        SetObjectTaint replaces the taint signals on an object; an empty list
        clears them. A capability without allow_tainted_read is refused any read
        of a tainted object. Gated by its own Cedar action, SetObjectTaint:
        clearing a flag re-opens content to agents, which write access to a
        collection should not imply.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="SetObjectTaint",
                service_name="paladin.data.v1.ObjectService",
                input=SetObjectTaintRequest,
                output=Object,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

